/* 11AM Literature: complete, atomic, offline reader; GENERATED by scripts/build.py.
 * Scope is strictly /11am-literature/. PDF assets are not cached.
 * Browser storage can be evicted and fonts are always optional.
 */
const CACHE_PREFIX = '11am-lit-reader-';
const BOOK_CACHE = CACHE_PREFIX + '946b47fd4e04';
const FONT_CACHE = '11am-lit-fonts-v1';
const APP_SHELL = [
  './index.html', './manifest.webmanifest', './offline-update.js',
  './icons/icon-192.png', './icons/icon-512.png',
  './og-image.png', './404.html', './sitemap.xml'
];
const SCOPE = new URL(self.registration.scope);
const BOOK_URL = new URL('./index.html', SCOPE).href;

function allowedFont(url) {
  return url.protocol === 'https:' && (
    (url.hostname === 'fonts.googleapis.com' && url.pathname.startsWith('/css2')) ||
    (url.hostname === 'fonts.gstatic.com' && url.pathname.startsWith('/s/'))
  );
}
self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(BOOK_CACHE);
    // A partial download never becomes the active reader.
    await cache.addAll(APP_SHELL);
    await self.skipWaiting();
  })());
});
self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter(name => name.startsWith(CACHE_PREFIX) && name !== BOOK_CACHE)
      .map(name => caches.delete(name)));
    await self.clients.claim();
  })());
});
self.addEventListener('message', event => {
  if (event.data?.type !== 'SAVE_READER') return;
  const port = event.ports?.[0];
  event.waitUntil((async () => {
    try {
      // Refreshing uses the current worker's complete required asset set.
      const cache = await caches.open(BOOK_CACHE);
      const present = await Promise.all(APP_SHELL.map(p => cache.match(p)));
      if (present.some(p => !p)) await cache.addAll(APP_SHELL);
      port?.postMessage({ok:true});
    } catch (error) {
      port?.postMessage({ok:false,error:String(error)});
    }
  })());
});
self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (allowedFont(url)) {
    event.respondWith((async () => {
      const cache = await caches.open(FONT_CACHE);
      const saved = await cache.match(req, {ignoreVary:true});
      if (saved) return saved;
      try {
        const response = await fetch(req);
        if (response.ok || response.type === 'opaque')
          event.waitUntil(cache.put(req,response.clone()).catch(()=>{}));
        return response;
      } catch { return Response.error(); }
    })());
    return;
  }
  if (url.origin !== SCOPE.origin || !url.pathname.startsWith(SCOPE.pathname)) return;
  if (url.pathname.toLowerCase().endsWith('.pdf')) return;
  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      // Navigation is cache-first; an upgraded worker installs a complete
      // new version and the client offers an explicit edition reload.
      const cache = await caches.open(BOOK_CACHE);
      const saved = await cache.match(BOOK_URL);
      if (saved) return saved;
      try { return await fetch(req); } catch { return Response.error(); }
    })());
    return;
  }
  event.respondWith((async () => {
    const cache = await caches.open(BOOK_CACHE);
    const saved = await cache.match(req);
    return saved || fetch(req);
  })());
});
